export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  const scene = new BABYLON.Scene(engine);
  scene.useRightHandedSystem = true;

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(-0.4, 4.39, -0.22));
  camera.alpha = 0.822;
  camera.beta = 1.661;
  camera.radius = 17.629;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 10000;

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);

  var dirLight = new BABYLON.DirectionalLight("dirLight", new BABYLON.Vector3(0, -1, 0.5), scene);
  dirLight.position = new BABYLON.Vector3(10, 10, -10);
  dirLight.intensity = 1.0;

  const TEXTURE_FOLDER = "https://www.babylonjs-playground.com/textures/";

  const GROUND_SIZE = 100;
  var GRASS_HEIGHT = 1.0;
  var GRASS_SPACING = 0.3;

  var INSTANCES = (GROUND_SIZE / GRASS_SPACING) * (GROUND_SIZE / GRASS_SPACING);
  INSTANCES = Math.round(INSTANCES * 100) / 100;

  var grass;

  var groundMaterial = new BABYLON.StandardMaterial("groundMaterial", scene);
  groundMaterial.diffuseTexture = new BABYLON.Texture(); // some material for the ground.
  groundMaterial.diffuseTexture = new BABYLON.Texture(TEXTURE_FOLDER + "grass.png", scene);
  groundMaterial.bumpTexture = new BABYLON.Texture(TEXTURE_FOLDER + "rockn.png", scene);
  groundMaterial.diffuseTexture.uScale = groundMaterial.bumpTexture.uScale = 5;
  groundMaterial.diffuseTexture.vScale = groundMaterial.bumpTexture.vScale = 7;
  groundMaterial.backFaceCulling = false;

  const ground = BABYLON.MeshBuilder.CreateGroundFromHeightMap("gdhm", "/images/textures/heightMap.png", {
    width: 5,
    height: 5,
    subdivisions: 500,
    maxHeight: 1,
    onReady: () => {
      ground.material = groundMaterial;
      ground.receiveShadows = true;
      addGrass();
    },
  });

  ground.visibility = 0;

  const addGrass = () => {
    if (GRASS_SPACING <= 0) {
      GRASS_SPACING = 1;
      INSTANCES = (GROUND_SIZE / GRASS_SPACING) * (GROUND_SIZE / GRASS_SPACING);
    }
    grass = BABYLON.MeshBuilder.CreateGround(
      "grass",
      {
        width: GRASS_HEIGHT * 0.75,
        height: GRASS_HEIGHT,
      },
      scene
    );
    grass.rotation.x = Math.PI * 0.5;
    grass.bakeCurrentTransformIntoVertices();
    BABYLON.NodeMaterial.ParseFromSnippetAsync("#8WH2KS#22", scene).then((nodeMaterial) => {
      grass.material = nodeMaterial;
      nodeMaterial.backFaceCulling = false;
    });

    let offset = 16 * 3;
    let matricesData = new Float32Array(offset * INSTANCES);
    let index = 0;
    let x = 0,
      z = 0;
    for (x = -GROUND_SIZE / 2; x < GROUND_SIZE / 2; x += GRASS_SPACING) {
      for (z = -GROUND_SIZE / 2; z < GROUND_SIZE / 2; z += GRASS_SPACING) {
        let positionX = x + Math.random() * GRASS_SPACING;
        let positionZ = z + Math.random() * GRASS_SPACING;

        const scale = new BABYLON.Vector3(1, 1.5 + Math.random(), 1);
        const rotation = BABYLON.Quaternion.RotationYawPitchRoll(Math.PI * Math.random(), 0, 0);
        const trans = new BABYLON.Vector3(positionX, ground.getHeightAtCoordinates(positionX, positionZ) + (GRASS_HEIGHT * scale.y) / 2, positionZ);
        BABYLON.Matrix.Compose(scale, rotation, trans).copyToArray(matricesData, index * 16 * 3);
        index++;
      }
    }
    grass.thinInstanceSetBuffer("matrix", matricesData);
  };

  BABYLON.Effect.ShadersStore["stylizedSkyVertexShader"] = `
        precision highp float;

        attribute vec3 position;
        uniform mat4 world;
        uniform mat4 worldViewProjection;
        varying vec3 vWorldPosition;

        void main() {
            vec4 worldPos = world * vec4(position, 1.0);
            vWorldPosition = worldPos.xyz;
            gl_Position = worldViewProjection * worldPos;
        }
    `;

  BABYLON.Effect.ShadersStore["stylizedSkyFragmentShader"] = `
        precision highp float;

        varying vec3 vWorldPosition;

        uniform vec3 topColor;
        uniform vec3 bottomColor;
        uniform vec3 sunDirection;
        uniform vec3 sunColor;
        uniform float sunIntensity;

        void main() {
            vec3 viewDir = normalize(vWorldPosition);
            float t = clamp(viewDir.y * 0.5 + 0.5, 0.0, 1.0);
            vec3 skyColor = mix(bottomColor, topColor, t);

            float sunAmount = max(dot(viewDir, normalize(sunDirection)), 0.0);
            sunAmount = pow(sunAmount, 300.0);
            vec3 finalColor = skyColor + sunColor * sunAmount * sunIntensity;

            gl_FragColor = vec4(finalColor, 1.0);
        }
    `;

  const skyMaterial = new BABYLON.ShaderMaterial(
    "stylizedSky",
    scene,
    {
      vertex: "stylizedSky",
      fragment: "stylizedCloud",
    },
    {
      attributes: ["position"],
      // uniforms: ["worldViewProjection", "world", "topColor", "bottomColor", "sunColor", "sunDirection", "sunIntensity"]
      uniforms: ["worldViewProjection", "world", "topColor", "bottomColor", "sunDirection", "sunColor", "sunIntensity", "time"],
    }
  );

  skyMaterial.setVector3("topColor", new BABYLON.Vector3(0.3, 0.6, 1.0));
  skyMaterial.setVector3("bottomColor", new BABYLON.Vector3(0.8, 0.7, 1.0));
  skyMaterial.setVector3("sunDirection", new BABYLON.Vector3(0.5, 1.0, 0.0));
  skyMaterial.setVector3("sunColor", new BABYLON.Vector3(1.0, 0.8, 0.5));
  skyMaterial.setFloat("sunIntensity", 1.2);
  skyMaterial.setVector2("cloudScale", new BABYLON.Vector2(4.0, 6.0));
  skyMaterial.setVector2("cloudSpeed", new BABYLON.Vector2(0.02, 0.01));
  skyMaterial.setVector2("cloudOffset", new BABYLON.Vector2(Math.random() * 100.0, Math.random() * 100.0));

  // const skySphere = BABYLON.MeshBuilder.CreateSphere("sky", { segments: 32, diameter: 1000, slice: 0.5,  arc: 1,}, scene);
  const skySphere = BABYLON.MeshBuilder.CreateSphere("sky", { segments: 32, diameter: 10000 }, scene);
  skySphere.material = skyMaterial;
  skySphere.isPickable = false;
  skySphere.material.backFaceCulling = false;
  skySphere.infiniteDistance = false;

  scene.registerBeforeRender(() => {
    skySphere.position.copyFrom(camera.position);
  });

  BABYLON.Effect.ShadersStore["stylizedCloudFragmentShader"] = `
        precision highp float;

        varying vec3 vWorldPosition;

        uniform vec3 topColor;
        uniform vec3 bottomColor;
        uniform vec3 sunDirection;
        uniform vec3 sunColor;
        uniform float sunIntensity;
        uniform float time;
        uniform vec2 cloudScale;
        uniform vec2 cloudSpeed;
        uniform vec2 cloudOffset;

        float hash(vec2 p) {
            return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
        }
        float noise(vec2 p) {
            vec2 i = floor(p);
            vec2 f = fract(p);
            vec2 u = f * f * (3.0 - 2.0 * f);
            return mix(
                mix(hash(i + vec2(0.0, 0.0)), hash(i + vec2(1.0, 0.0)), u.x),
                mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
                u.y
            );
        }

        // fractal brownian motion (fbm)
        float fbm(vec2 p) {
            float value = 0.0;
            float amplitude = 0.5;
            float frequency = 1.0;
            for (int i = 0; i < 7; i++) {
                value += amplitude * noise(p * frequency);
                frequency *= 2.0;
                amplitude *= 0.5;
            }
            return value;
        }

        void main() {
            vec3 viewDir = normalize(vWorldPosition);
            float t = clamp(viewDir.y * 0.5 + 0.5, 0.0, 1.0);
            vec3 skyColor = mix(bottomColor, topColor, t);

            float sunAmount = max(dot(viewDir, normalize(sunDirection)), 0.0);
            sunAmount = pow(sunAmount, 300.0);
            vec3 finalColor = skyColor + sunColor * sunAmount * sunIntensity;

            // animated cloud UV
            // vec2 cloudUV = viewDir.xz * 4.0 + vec2(time * 0.03, time * 0.01);
            // float cloudNoise = fbm(cloudUV);
            // float cloudMask = smoothstep(0.55, 0.75, cloudNoise);
            // vec3 cloudColor = vec3(1.0);
            // finalColor = mix(finalColor, cloudColor, cloudMask * 0.6);

            vec3 dir = normalize(vWorldPosition);
            vec3 up = vec3(0.0, 1.3, 0.0);
            vec3 projected = normalize(reflect(dir, up));

            float u = projected.x * 0.5 + 0.5;
            float v = projected.z * 0.5 + 0.5;

            vec2 cloudUV = vec2(u, v) * cloudScale + cloudSpeed * time + cloudOffset;
            float cloudNoise = fbm(cloudUV);

            float heightFactor = smoothstep(0.0, 0.3, viewDir.y);
            float cloudMask = smoothstep(0.4, 0.7, cloudNoise) * heightFactor;

            vec3 cloudColor = mix(vec3(1.0), skyColor, 0.3);
            finalColor = mix(finalColor, cloudColor, cloudMask * 0.6);

            gl_FragColor = vec4(finalColor, 1.0);
        }
    `;

  let startTime = Date.now();

  scene.registerBeforeRender(() => {
    skySphere.position.copyFrom(camera.position);
    const time = (Date.now() - startTime) * 0.005;
    skyMaterial.setFloat("time", time);
  });

  BABYLON.Effect.ShadersStore["toonVertexShader"] = `
        precision highp float;

        attribute vec3 position;
        attribute vec3 normal;
        attribute vec2 uv;

        uniform mat4 world;
        uniform mat4 worldViewProjection;

        varying vec3 vNormalW;
        varying vec3 vPositionW;
        varying vec2 vUV;

        void main(void) {
            vec4 worldPos = world * vec4(position, 1.0);
            vPositionW = worldPos.xyz;
            vNormalW = normalize(mat3(world) * normal);
            vUV = uv;
            gl_Position = worldViewProjection * vec4(position, 1.0);
        }
    `;

  BABYLON.Effect.ShadersStore["toonFragmentShader"] = `
        precision highp float;

        varying vec3 vNormalW;
        varying vec3 vPositionW;
        varying vec2 vUV;

        uniform vec3 lightDirection;
        uniform vec3 baseColor;
        uniform sampler2D albedoTexture;
        uniform float hasAlbedoTexture;

        void main(void) {
            float NdotL = dot(normalize(vNormalW), -normalize(lightDirection));
            float light = 0.5 * NdotL + 0.5;

            vec3 texColor = texture2D(albedoTexture, vUV).rgb;
            vec3 surfaceColor = mix(baseColor, texColor, hasAlbedoTexture);
            vec3 pastel = mix(surfaceColor, vec3(1.0), 0.1);

            vec3 finalColor;
            if (light > 0.5) {
                finalColor = pastel * 1.05;
            } else {
                finalColor = pastel * 0.75;
            }

            gl_FragColor = vec4(finalColor, 1.0);
        }
    `;

  let rootMesh;

  BABYLON.SceneLoader.ImportMeshAsync("", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", "motorcycle.glb", scene).then((result) => {
    rootMesh = result.meshes[0];
    rootMesh.scaling.scaleInPlace(5);

    var defaultPipeline = new BABYLON.DefaultRenderingPipeline("DRPP", true, scene, [camera]);
    defaultPipeline.fxaaEnabled = true;
    defaultPipeline.imageProcessingEnabled = false;
    defaultPipeline.samples = 4;

    engine.setHardwareScalingLevel(0.7);

    rootMesh.getChildMeshes().forEach((m) => {
      if (m.name === "Cylinder.013_FireCar.001_0") {
        camera.setTarget = m.position.clone();

        camera.useAutoRotationBehavior = true;
        camera.autoRotationBehavior.idleRotationSpeed = 0.37;
      }
      if (m.material) {
        const mat = m.material;
        const albedoTex = mat.albedoTexture || mat.diffuseTexture;

        const toonMaterial = new BABYLON.ShaderMaterial(
          "toon",
          scene,
          {
            vertex: "toon",
            fragment: "toon",
          },
          {
            attributes: ["position", "normal", "uv"],
            uniforms: ["world", "worldViewProjection", "lightDirection", "baseColor", "hasAlbedoTexture"],
            samplers: ["albedoTexture"],
          }
        );

        scene.registerBeforeRender(() => {
          const time = performance.now() * 0.001;
          const noiseX = Math.sin(time * 0.3) * 0.3;
          const noiseY = Math.cos(time * 0.2) * 0.3;
          const noiseZ = Math.sin(time * 0.4 + 10.0) * 0.3;
          dirLight.direction = new BABYLON.Vector3(0 + noiseX, -1 + noiseY, 0.5 + noiseZ).normalize();

          toonMaterial.setVector3("lightDirection", dirLight.direction);
        });
        toonMaterial.setColor3("baseColor", mat.albedoColor || new BABYLON.Color3(1.0, 0.8, 0.6));

        if (albedoTex) {
          toonMaterial.setTexture("albedoTexture", albedoTex);
          toonMaterial.setFloat("hasAlbedoTexture", 1.0);
        } else {
          toonMaterial.setFloat("hasAlbedoTexture", 0.0);
        }

        m.material = toonMaterial;
      }
    });
  });

  return scene;
}
